package negocio;
import java.time.LocalDateTime;
public class ConvocatoriaComunidad {
 private long id,reservaId,clienteCreadorId,perfilCreadorId; private Long categoriaDeportivaId; private PosicionJugador posicionBuscada; private int participantesConfirmados,lugaresBuscados; private EstadoConvocatoriaComunidad estado=EstadoConvocatoriaComunidad.BORRADOR; private String comentario; private MotivoCierreConvocatoria motivoCierre; private LocalDateTime fechaPublicacion,fechaCierre,fechaExpiracion,fechaCreacion,fechaActualizacion; private long version;
 public long getId(){return id;} public void setId(long v){id=v;} public long getReservaId(){return reservaId;} public void setReservaId(long v){reservaId=v;} public long getClienteCreadorId(){return clienteCreadorId;} public void setClienteCreadorId(long v){clienteCreadorId=v;} public long getPerfilCreadorId(){return perfilCreadorId;} public void setPerfilCreadorId(long v){perfilCreadorId=v;} public Long getCategoriaDeportivaId(){return categoriaDeportivaId;} public void setCategoriaDeportivaId(Long v){categoriaDeportivaId=v;} public PosicionJugador getPosicionBuscada(){return posicionBuscada;} public void setPosicionBuscada(PosicionJugador v){posicionBuscada=v;} public int getParticipantesConfirmados(){return participantesConfirmados;} public void setParticipantesConfirmados(int v){participantesConfirmados=v;} public int getLugaresBuscados(){return lugaresBuscados;} public void setLugaresBuscados(int v){lugaresBuscados=v;} public EstadoConvocatoriaComunidad getEstado(){return estado;} public void setEstado(EstadoConvocatoriaComunidad v){estado=v;} public String getComentario(){return comentario;} public void setComentario(String v){comentario=v;} public MotivoCierreConvocatoria getMotivoCierre(){return motivoCierre;} public void setMotivoCierre(MotivoCierreConvocatoria v){motivoCierre=v;} public LocalDateTime getFechaPublicacion(){return fechaPublicacion;} public void setFechaPublicacion(LocalDateTime v){fechaPublicacion=v;} public LocalDateTime getFechaCierre(){return fechaCierre;} public void setFechaCierre(LocalDateTime v){fechaCierre=v;} public LocalDateTime getFechaExpiracion(){return fechaExpiracion;} public void setFechaExpiracion(LocalDateTime v){fechaExpiracion=v;} public LocalDateTime getFechaCreacion(){return fechaCreacion;} public void setFechaCreacion(LocalDateTime v){fechaCreacion=v;} public LocalDateTime getFechaActualizacion(){return fechaActualizacion;} public void setFechaActualizacion(LocalDateTime v){fechaActualizacion=v;} public long getVersion(){return version;} public void setVersion(long v){version=v;}
 public Integer getClaveActiva(){return estado!=null&&estado.esActiva()?1:null;} public int lugaresDisponibles(){return estado!=null&&estado.esActiva()?Math.max(0,Math.min(lugaresBuscados,4-participantesConfirmados)):0;} public void validar(){if(reservaId<=0||clienteCreadorId<=0||perfilCreadorId<=0)throw new IllegalArgumentException("La reserva, el cliente y el perfil son obligatorios.");if(estado==null)throw new IllegalArgumentException("El estado es obligatorio.");if(participantesConfirmados<1||participantesConfirmados>3)throw new IllegalArgumentException("Los participantes confirmados deben estar entre 1 y 3.");if(lugaresBuscados<1||lugaresBuscados>3||participantesConfirmados+lugaresBuscados>4)throw new IllegalArgumentException("La convocatoria no puede superar cuatro participantes.");if(comentario!=null&&comentario.trim().length()>500)throw new IllegalArgumentException("El comentario no puede superar 500 caracteres.");if(fechaExpiracion==null)throw new IllegalArgumentException("La expiración es obligatoria.");}
}